                    v_lz += (al2 * (vgx[(h & 2 ? (h & 1 ? 5744 : 4104) : (h & 1 ? 4704 : 4184))] - zlzk * vgx[(h & 2 ? (h & 1 ? 5584 : 3944) : (h & 1 ? 4544 : 4024))]) - (h & 2 ? (h & 1 ? 2.0 : 0.0) : (h & 1 ? 1.0 : 0.0)) * vgx[(h & 2 ? (h & 1 ? 4944 : 3944) : (h & 1 ? 3904 : 4024))]) * s;
