                    v_lz += (al2 * (vgx[(h & 1 ? 5488 : 4208)] - zlzk * vgx[(h & 1 ? 5248 : 3968)]) - (h & 1 ? 1.0 : 0.0) * vgx[(h & 1 ? 4288 : 3968)]) * s;
                    s = dd_cache[(h & 1 ? 5744 : 6224)] * (vgx[(h & 1 ? 960 : 560)] * vgx[(h & 1 ? 1920 : 2880)]);
