                    v_kz += (ak2 * vgx[(h & 1 ? 5728 : 4208)] - (h & 1 ? 2.0 : 0.0) * vgx[(h & 1 ? 5248 : 3968)]) * s;
                    v_lz += (al2 * (vgx[(h & 1 ? 5728 : 4208)] - zlzk * vgx[(h & 1 ? 5488 : 3968)]) - (h & 1 ? 1.0 : 0.0) * vgx[(h & 1 ? 4528 : 3968)]) * s;
