// (ff|ps): 300 outputs, 8 threads x 32 quartets per block, g_size 60
__global__ static
__launch_bounds__(256, 1)
void rys_ejk_ip1_gen_3310(JKENERGY_KERNEL_ARGS)
{
    JKENERGY_KERNEL_SETUP();
    constexpr int nsq_per_block = 32;
    constexpr int gout_stride = 8;
