                    v_lx += (al2 * (vgx[1856] - xlxk * vgx[1216])) * s;
                    s = dd_cache[3392] * (vgx[480] * vgx[3840]);
                    s += dd_cache[4032] * (vgx[320] * vgx[4000]);
                    s += dd_cache[4992] * (vgx[160] * vgx[4160]);
                    s += dd_cache[6272] * (vgx[0] * vgx[4320]);
                    v_iy += (ai2 * vgx[2688] - 3 * vgx[2624]) * s;
                    v_ky += (ak2 * vgx[3296] - 1 * vgx[2016]) * s;
                    v_ly += (al2 * (vgx[3296] - ylyk * vgx[2656])) * s;
                    s = dd_cache[512] * (vgx[960] * vgx[3840]);
                    s += dd_cache[1472] * (vgx[800] * vgx[4000]);
                    s += dd_cache[2752] * (vgx[640] * vgx[4160]);
                    s += dd_cache[6912] * (vgx[320] * vgx[4480]);
                    s += dd_cache[7872] * (vgx[160] * vgx[4640]);
                    s += dd_cache[9152] * (vgx[0] * vgx[4800]);
                    v_iy += (ai2 * vgx[2208] - 3 * vgx[2144]) * s;
                    v_ky += (ak2 * vgx[2816]) * s;
                    v_ly += (al2 * (vgx[2816] - ylyk * vgx[2176])) * s;
                    s = dd_cache[3712] * (vgx[320] * vgx[3840]);
                    s += dd_cache[4672] * (vgx[160] * vgx[4000]);
                    s += dd_cache[5952] * (vgx[0] * vgx[4160]);
                    v_iy += (ai2 * vgx[2848] - 3 * vgx[2784]) * s;
                    v_ky += (ak2 * vgx[3456] - 1 * vgx[2176]) * s;
                    v_ly += (al2 * (vgx[3456] - ylyk * vgx[2816])) * s;
                    s = dd_cache[1152] * (vgx[800] * vgx[3840]);
                    s += dd_cache[2432] * (vgx[640] * vgx[4000]);
                    s += dd_cache[7552] * (vgx[160] * vgx[4480]);
                    s += dd_cache[8832] * (vgx[0] * vgx[4640]);
                    v_iy += (ai2 * vgx[2368] - 3 * vgx[2304]) * s;
                    v_ky += (ak2 * vgx[2976]) * s;
                    v_ly += (al2 * (vgx[2976] - ylyk * vgx[2336])) * s;
                    s = dd_cache[4352] * (vgx[160] * vgx[3840]);
                    s += dd_cache[5632] * (vgx[0] * vgx[4000]);
                    v_iy += (ai2 * vgx[3008] - 3 * vgx[2944]) * s;
                    v_ky += (ak2 * vgx[3616] - 1 * vgx[2336]) * s;
                    v_ly += (al2 * (vgx[3616] - ylyk * vgx[2976])) * s;
                    s = dd_cache[2112] * (vgx[640] * vgx[3840]);
                    s += dd_cache[8512] * (vgx[0] * vgx[4480]);
                    v_iy += (ai2 * vgx[2528] - 3 * vgx[2464]) * s;
                    v_ky += (ak2 * vgx[3136]) * s;
                    v_ly += (al2 * (vgx[3136] - ylyk * vgx[2496])) * s;
                    s = dd_cache[5312] * (vgx[0] * vgx[3840]);
                    v_iy += (ai2 * vgx[3168] - 3 * vgx[3104]) * s;
                    v_ky += (ak2 * vgx[3776] - 1 * vgx[2496]) * s;
                    v_ly += (al2 * (vgx[3776] - ylyk * vgx[3136])) * s;
                    s = dd_cache[6688] * (vgx[480] * vgx[1920]);
                    s += dd_cache[7008] * (vgx[320] * vgx[2080]);
                    s += dd_cache[7648] * (vgx[160] * vgx[2240]);
                    s += dd_cache[8608] * (vgx[0] * vgx[2400]);
                    v_iz += (ai2 * vgx[4608] - 3 * vgx[4544]) * s;
                    v_kz += (ak2 * vgx[5216] - 1 * vgx[3936]) * s;
                    v_lz += (al2 * (vgx[5216] - zlzk * vgx[4576])) * s;
                    s = dd_cache[928] * (vgx[960] * vgx[1920]);
                    s += dd_cache[1568] * (vgx[800] * vgx[2080]);
                    s += dd_cache[2528] * (vgx[640] * vgx[2240]);
                    s += dd_cache[4128] * (vgx[320] * vgx[2560]);
                    s += dd_cache[4768] * (vgx[160] * vgx[2720]);
                    s += dd_cache[5728] * (vgx[0] * vgx[2880]);
                    v_iz += (ai2 * vgx[4128] - 3 * vgx[4064]) * s;
                    v_kz += (ak2 * vgx[4736]) * s;
                    v_lz += (al2 * (vgx[4736] - zlzk * vgx[4096])) * s;
                    s = dd_cache[7328] * (vgx[320] * vgx[1920]);
                    s += dd_cache[7968] * (vgx[160] * vgx[2080]);
                    s += dd_cache[8928] * (vgx[0] * vgx[2240]);
                    v_iz += (ai2 * vgx[4768] - 3 * vgx[4704]) * s;
                    v_kz += (ak2 * vgx[5376] - 1 * vgx[4096]) * s;
                    v_lz += (al2 * (vgx[5376] - zlzk * vgx[4736])) * s;
                    s = dd_cache[1888] * (vgx[800] * vgx[1920]);
                    s += dd_cache[2848] * (vgx[640] * vgx[2080]);
                    s += dd_cache[5088] * (vgx[160] * vgx[2560]);
                    s += dd_cache[6048] * (vgx[0] * vgx[2720]);
                    v_iz += (ai2 * vgx[4288] - 3 * vgx[4224]) * s;
                    v_kz += (ak2 * vgx[4896]) * s;
                    v_lz += (al2 * (vgx[4896] - zlzk * vgx[4256])) * s;
                    s = dd_cache[8288] * (vgx[160] * vgx[1920]);
                    s += dd_cache[9248] * (vgx[0] * vgx[2080]);
                    v_iz += (ai2 * vgx[4928] - 3 * vgx[4864]) * s;
                    v_kz += (ak2 * vgx[5536] - 1 * vgx[4256]) * s;
                    v_lz += (al2 * (vgx[5536] - zlzk * vgx[4896])) * s;
                    s = dd_cache[3168] * (vgx[640] * vgx[1920]);
                    s += dd_cache[6368] * (vgx[0] * vgx[2560]);
                    v_iz += (ai2 * vgx[4448] - 3 * vgx[4384]) * s;
                    v_kz += (ak2 * vgx[5056]) * s;
                    v_lz += (al2 * (vgx[5056] - zlzk * vgx[4416])) * s;
                    s = dd_cache[9568] * (vgx[0] * vgx[1920]);
                    v_iz += (ai2 * vgx[5088] - 3 * vgx[5024]) * s;
                    v_kz += (ak2 * vgx[5696] - 1 * vgx[4416]) * s;
                    v_lz += (al2 * (vgx[5696] - zlzk * vgx[5056])) * s;
                    break;
                    }
                }
            }
        }
        if (task_id >= ntasks) {
            break;
        }
        int ka = bas[ksh*BAS_SLOTS+ATOM_OF];
        int la = bas[lsh*BAS_SLOTS+ATOM_OF];
        double *ejk = jk.ejk;
        atomicAdd(ejk+ka*3+0, v_kx);
        atomicAdd(ejk+ka*3+1, v_ky);
        atomicAdd(ejk+ka*3+2, v_kz);
        atomicAdd(ejk+la*3+0, v_lx);
        atomicAdd(ejk+la*3+1, v_ly);
        atomicAdd(ejk+la*3+2, v_lz);
        // translational invariance: j's derivative is minus the sum of the other three centers'
        v_jx += v_kx + v_lx;
        v_jy += v_ky + v_ly;
        v_jz += v_kz + v_lz;
    }
    int ia = bas[ish*BAS_SLOTS+ATOM_OF];
    int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
    double *ejk = jk.ejk;
    atomicAdd(ejk+ia*3+0, v_ix);
    atomicAdd(ejk+ia*3+1, v_iy);
    atomicAdd(ejk+ia*3+2, v_iz);
    atomicAdd(ejk+ja*3+0, -(v_ix + v_jx));
    atomicAdd(ejk+ja*3+1, -(v_iy + v_jy));
    atomicAdd(ejk+ja*3+2, -(v_iz + v_jz));
}
}
// (ds|dd): 216 outputs, 8 threads x 32 quartets per block, g_size 48
__global__ static
__launch_bounds__(256, 1)
void rys_ejk_ip1_gen_2022(JKENERGY_KERNEL_ARGS)
{
    JKENERGY_KERNEL_SETUP();
    constexpr int nsq_per_block = 32;
    constexpr int gout_stride = 8;
    int t_id = gout_id * nsq_per_block + sq_id;
    int threads = nsq_per_block * gout_stride;
    int nbas = envs.nbas;
    int *bas = envs.bas;
    double *env = envs.env;
    int iprim = bounds.iprim;
    int jprim = bounds.jprim;
    int kprim = bounds.kprim;
    int lprim = bounds.lprim;
    int nroots = bounds.nroots;
    double *rlrk = shared_memory + sq_id;
    double *Rpq = shared_memory + nsq_per_block * 3 + sq_id;
    double *gx = shared_memory + nsq_per_block * 6 + sq_id;
    double *rw = shared_memory + nsq_per_block * 150 + sq_id;
    double *cicj_cache = shared_memory + nsq_per_block * (150+nroots*2);

    uint32_t *bas_kl_idx = pool + worker_id * QUEUE_DEPTH;
    double *dd_cache = dd_pool + worker_id * 6912 + sq_id;
while (1) {
    __syncthreads();
    if (t_id == 0) {
        int task_id = atomicAdd(head, 1);
        int batch_kl = task_id / bounds.npairs_ij;
        pair_ij = task_id - bounds.npairs_ij * batch_kl;
        pair_kl0 = batch_kl * (QUEUE_DEPTH - 512);
        uint32_t bas_ij = bounds.pair_ij_mapping[pair_ij];
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    if (pair_kl0 >= bounds.npairs_kl) {
        break;
    }
    if (jk.lr_factor != 0) {
        _fill_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                        q_cond_ij, q_cond_kl,
                        (int *)shared_memory, jk, envs, bounds);
    } else {
        _fill_sr_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                           q_cond_ij, q_cond_kl,
                           s_cond_ij, s_cond_kl, diffuse_exps,
                           (int *)shared_memory, jk, envs, bounds);
    }
    if (ntasks == 0) {
        continue;
    }
    if (t_id == 0) {
        expi = bas[ish*BAS_SLOTS+PTR_EXP];
        expj = bas[jsh*BAS_SLOTS+PTR_EXP];
    }
    __syncthreads();
    if (t_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[t_id] = env[ri_ptr+t_id];
        rjri[t_id] = env[rj_ptr+t_id] - ri[t_id];
    }
    __syncthreads();
    double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
    double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
    double xjxi = rjri[0];
    double yjyi = rjri[1];
    double zjzi = rjri[2];
    for (int ij = t_id; ij < iprim*jprim; ij += threads) {
        int ip = ij / jprim;
        int jp = ij % jprim;
        double ai = env[expi+ip];
        double aj = env[expj+jp];
        double aij = ai + aj;
        double theta_ij = ai * aj / aij;
        double rr_ij = xjxi*xjxi + yjyi*yjyi + zjzi*zjzi;
        double Kab = exp(-theta_ij * rr_ij);
        cicj_cache[ij] = ci[ip] * cj[jp] * Kab;
    }
    __syncthreads();

    int *ao_loc = envs.ao_loc;
    int nao = ao_loc[nbas];
    double *dm = jk.dm;
    double v_ix = 0;
    double v_iy = 0;
    double v_iz = 0;
    double v_jx = 0;
    double v_jy = 0;
    double v_jz = 0;
    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += nsq_per_block) {
        // another thread of this quartet may still read the previous task's dd_cache
        __syncthreads();
        uint32_t bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (ish*nbas+jsh == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        int i0 = ao_loc[ish];
        int j0 = ao_loc[jsh];
        int k0 = ao_loc[ksh];
        int l0 = ao_loc[lsh];
        int expk = bas[ksh*BAS_SLOTS+PTR_EXP];
        int expl = bas[lsh*BAS_SLOTS+PTR_EXP];
        int ck = bas[ksh*BAS_SLOTS+PTR_COEFF];
        int cl = bas[lsh*BAS_SLOTS+PTR_COEFF];
        int rk = bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        int rl = bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        double xlxk = env[rl+0] - env[rk+0];
        double ylyk = env[rl+1] - env[rk+1];
        double zlzk = env[rl+2] - env[rk+2];
        if (gout_id == 0) {
            rlrk[0] = xlxk;
            rlrk[32] = ylyk;
            rlrk[2*32] = zlzk;
        }
        double v_kx = 0;
        double v_ky = 0;
        double v_kz = 0;
        double v_lx = 0;
        double v_ly = 0;
        double v_lz = 0;
        int do_j = jk.j_factor != 0.;
        int do_k = jk.k_factor != 0.;
        if (jk.n_dm == 1) {
            for (int n = gout_id; n < 216; n+=8) {
                int i = n % 6;
                int j = n / 6 % 1;
                int k = n / 6 % 6;
                int l = n / 36;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _li = _l*nao+_i;
                int _ki = _k*nao+_i;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += jk.k_factor * (dm[_jk] * dm[_li] + dm[_jl] * dm[_ki]);
                }
                if (do_j) {
                    dd += jk.j_factor * dm[_ji] * dm[_lk];
                }
                dd_cache[n*32] = fac_sym * dd;
            }
        } else {
            double *dmb = dm + nao * nao;
            for (int n = gout_id; n < 216; n+=8) {
                int i = n % 6;
                int j = n / 6 % 1;
                int k = n / 6 % 6;
                int l = n / 36;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _li = _l*nao+_i;
                int _ki = _k*nao+_i;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += jk.k_factor * (dm [_jk] * dm [_li] + dm [_jl] * dm [_ki] +
                                         dmb[_jk] * dmb[_li] + dmb[_jl] * dmb[_ki]);
                }
                if (do_j) {
                    dd += jk.j_factor * (dm[_ji] + dmb[_ji]) * (dm[_lk] + dmb[_lk]);
                }
                dd_cache[n*32] = fac_sym * dd;
            }
        }
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            int kp = klp / lprim;
            int lp = klp % lprim;
            double ak = env[expk+kp];
            double al = env[expl+lp];
            double ak2 = ak * 2;
            double al2 = al * 2;
            double akl = ak + al;
            double al_akl = al / akl;
            double theta_kl = ak * al_akl;
            __syncthreads();
            if (gout_id == 0) {
                double Kcd = exp(-theta_kl * (xlxk*xlxk+ylyk*ylyk+zlzk*zlzk));
                double ckcl = env[ck+kp] * env[cl+lp] * Kcd;
                gx[0] = ckcl;
            }
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                if (fabs(cicj_cache[ijp]) < PRIM_CUTOFF) continue;
                int ip = ijp / jprim;
                int jp = ijp % jprim;
                double ai = env[expi+ip];
                double aj = env[expj+jp];
                double ai2 = ai * 2;
                double aj2 = aj * 2;
                double aij = ai + aj;
                double aj_aij = aj / aij;
                double xij = ri[0] + rjri[0] * aj_aij;
                double yij = ri[1] + rjri[1] * aj_aij;
                double zij = ri[2] + rjri[2] * aj_aij;
                double xkl = env[rk+0] + xlxk * al_akl;
                double ykl = env[rk+1] + ylyk * al_akl;
                double zkl = env[rk+2] + zlzk * al_akl;
                double xpq = xij - xkl;
                double ypq = yij - ykl;
                double zpq = zij - zkl;
                double theta = aij * akl / (aij + akl);
                double rr = xpq * xpq + ypq * ypq + zpq * zpq;
                __syncthreads();
                if (gout_id == 0) {
                    Rpq[0] = xpq;
                    Rpq[32] = ypq;
                    Rpq[2*32] = zpq;
                    double cicj = cicj_cache[ijp];
                    gx[48*32] = cicj / (aij*akl*sqrt(aij+akl));
                }
                rys_roots_for_k(nroots, theta, rr, rw, jk.omega, jk.lr_factor, jk.sr_factor, nsq_per_block, 8, gout_id);
                for (int irys = 0; irys < nroots; ++irys) {
                    __syncthreads();
                    double s0, s1, s2;
                    double rt = rw[irys*64];
                    double rt_aa = rt / (aij + akl);
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5/aij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    double b01 = .5/akl * (1 - rt_akl);
                    for (int n = gout_id; n < 3; n += 8) {
                        if (n == 2) {
                            gx[3072] = rw[irys*64+32];
                        }
                        double *_gx = gx + n * 1536;
                        double xjxi = rjri[n];
                        double Rpa = xjxi * aj_aij;
                        double c0x = Rpa - rt_aij * Rpq[n*32];
                        s0 = _gx[0];
                        s1 = c0x * s0;
                        _gx[32] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[64] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[96] = s2;
                        double xlxk = rlrk[n*32];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*32];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[128] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        _gx[256] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        _gx[384] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 3 * b01 *s0;
                        _gx[512] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 4 * b01 *s0;
                        _gx[640] = s2;
                        s0 = _gx[32];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[160] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 1 * b00 * _gx[128];
                        _gx[288] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 1 * b00 * _gx[256];
                        _gx[416] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 3 * b01 *s0;
                        s2 += 1 * b00 * _gx[384];
                        _gx[544] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 4 * b01 *s0;
                        s2 += 1 * b00 * _gx[512];
                        _gx[672] = s2;
                        s0 = _gx[64];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[32];
                        _gx[192] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 2 * b00 * _gx[160];
                        _gx[320] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 2 * b00 * _gx[288];
                        _gx[448] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 3 * b01 *s0;
                        s2 += 2 * b00 * _gx[416];
                        _gx[576] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 4 * b01 *s0;
                        s2 += 2 * b00 * _gx[544];
                        _gx[704] = s2;
                        s0 = _gx[96];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[64];
                        _gx[224] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 3 * b00 * _gx[192];
                        _gx[352] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 3 * b00 * _gx[320];
                        _gx[480] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 3 * b01 *s0;
                        s2 += 3 * b00 * _gx[448];
                        _gx[608] = s2;
                        s0 = s1;
                        s1 = s2;
