                    v_kz += (ak2 * vgx[3264]) * s;
                    v_lz += (al2 * (vgx[3264] - zlzk * vgx[2624])) * s;
                    s = dd_cache[800] * (vgx[352] * vgx[1280]);
                    s += dd_cache[896] * (vgx[320] * vgx[1312]);
                    s += dd_cache[1440] * (vgx[192] * vgx[1440]);
