                    v_ly += (al2 * (vgx[2304] - ylyk * vgx[1664])) * s;
                    s = dd_cache[2016] * (vgx[32] * vgx[2560]);
                    s += dd_cache[2144] * (vgx[0] * vgx[2592]);
                    v_iy += (ai2 * vgx[1856] - 2 * vgx[1792]) * s;
                    v_ky += (ak2 * vgx[2464]) * s;
                    v_ly += (al2 * (vgx[2464] - ylyk * vgx[1824])) * s;
                    s = dd_cache[192] * (vgx[480] * vgx[2560]);
                    s += dd_cache[832] * (vgx[320] * vgx[2720]);
                    s += dd_cache[1792] * (vgx[160] * vgx[2880]);
                    s += dd_cache[3072] * (vgx[0] * vgx[3040]);
                    v_iy += (ai2 * vgx[1408] - 3 * vgx[1344]) * s;
                    v_ky += (ak2 * vgx[2016]) * s;
                    v_ly += (al2 * (vgx[2016] - ylyk * vgx[1376])) * s;
                    s = dd_cache[1856] * (vgx[160] * vgx[1312]);
                    s += dd_cache[2720] * (vgx[32] * vgx[1440]);
                    s += dd_cache[2816] * (vgx[0] * vgx[1472]);
                    v_iz += (ai2 * vgx[2976] - 2 * vgx[2912]) * s;
