                    s += dd_cache[640] * (vgx[1280] * vgx[2720]);
                    v_ix += (ai2 * vgx[448] - 3 * vgx[384]) * s;
                    v_kx += (ak2 * vgx[1056]) * s;
                    v_lx += (al2 * (vgx[1056] - xlxk * vgx[416])) * s;
                    s = dd_cache[0] * (vgx[1280] * vgx[2560]);
                    v_ix += (ai2 * vgx[608] - 3 * vgx[544]) * s;
                    v_kx += (ak2 * vgx[1216]) * s;
                    v_lx += (al2 * (vgx[1216] - xlxk * vgx[576])) * s;
                    s = dd_cache[512] * (vgx[320] * vgx[2560]);
                    s += dd_cache[1472] * (vgx[160] * vgx[2720]);
                    s += dd_cache[2752] * (vgx[0] * vgx[2880]);
                    v_iy += (ai2 * vgx[1568] - 3 * vgx[1504]) * s;
                    v_ky += (ak2 * vgx[2176]) * s;
                    v_ly += (al2 * (vgx[2176] - ylyk * vgx[1536])) * s;
                    s = dd_cache[1152] * (vgx[160] * vgx[2560]);
                    s += dd_cache[2432] * (vgx[0] * vgx[2720]);
                    v_iy += (ai2 * vgx[1728] - 3 * vgx[1664]) * s;
                    v_ky += (ak2 * vgx[2336]) * s;
                    v_ly += (al2 * (vgx[2336] - ylyk * vgx[1696])) * s;
                    s = dd_cache[2112] * (vgx[0] * vgx[2560]);
                    v_iy += (ai2 * vgx[1888] - 3 * vgx[1824]) * s;
                    v_ky += (ak2 * vgx[2496]) * s;
                    v_ly += (al2 * (vgx[2496] - ylyk * vgx[1856])) * s;
                    s = dd_cache[928] * (vgx[320] * vgx[1280]);
                    s += dd_cache[1568] * (vgx[160] * vgx[1440]);
                    s += dd_cache[2528] * (vgx[0] * vgx[1600]);
                    v_iz += (ai2 * vgx[2848] - 3 * vgx[2784]) * s;
                    v_kz += (ak2 * vgx[3456]) * s;
                    v_lz += (al2 * (vgx[3456] - zlzk * vgx[2816])) * s;
                    s = dd_cache[1888] * (vgx[160] * vgx[1280]);
                    s += dd_cache[2848] * (vgx[0] * vgx[1440]);
                    v_iz += (ai2 * vgx[3008] - 3 * vgx[2944]) * s;
                    v_kz += (ak2 * vgx[3616]) * s;
                    v_lz += (al2 * (vgx[3616] - zlzk * vgx[2976])) * s;
                    s = dd_cache[3168] * (vgx[0] * vgx[1280]);
                    v_iz += (ai2 * vgx[3168] - 3 * vgx[3104]) * s;
                    v_kz += (ak2 * vgx[3776]) * s;
                    v_lz += (al2 * (vgx[3776] - zlzk * vgx[3136])) * s;
