    int iprim = bounds.iprim;
    int jprim = bounds.jprim;
    int kprim = bounds.kprim;
    int lprim = bounds.lprim;
    int nroots = bounds.nroots;
    double *rlrk = shared_memory + sq_id;
    double *Rpq = shared_memory + nsq_per_block * 3 + sq_id;
    double *gx = shared_memory + nsq_per_block * 6 + sq_id;
    double *rw = shared_memory + nsq_per_block * 96 + sq_id;
    double *cicj_cache = shared_memory + nsq_per_block * (96+nroots*2);

    uint32_t *bas_kl_idx = pool + worker_id * QUEUE_DEPTH;
    double *dd_cache = dd_pool + worker_id * 5760 + sq_id;
while (1) {
    __syncthreads();
    if (t_id == 0) {
        int task_id = atomicAdd(head, 1);
        int batch_kl = task_id / bounds.npairs_ij;
        pair_ij = task_id - bounds.npairs_ij * batch_kl;
        pair_kl0 = batch_kl * (QUEUE_DEPTH - 512);
        uint32_t bas_ij = bounds.pair_ij_mapping[pair_ij];
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    if (pair_kl0 >= bounds.npairs_kl) {
        break;
    }
    if (jk.lr_factor != 0) {
        _fill_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                        q_cond_ij, q_cond_kl,
                        (int *)shared_memory, jk, envs, bounds);
    } else {
        _fill_sr_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                           q_cond_ij, q_cond_kl,
                           s_cond_ij, s_cond_kl, diffuse_exps,
                           (int *)shared_memory, jk, envs, bounds);
    }
    if (ntasks == 0) {
        continue;
    }
    if (t_id == 0) {
        expi = bas[ish*BAS_SLOTS+PTR_EXP];
        expj = bas[jsh*BAS_SLOTS+PTR_EXP];
    }
    __syncthreads();
    if (t_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[t_id] = env[ri_ptr+t_id];
        rjri[t_id] = env[rj_ptr+t_id] - ri[t_id];
    }
    __syncthreads();
    double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
    double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
    double xjxi = rjri[0];
    double yjyi = rjri[1];
    double zjzi = rjri[2];
    for (int ij = t_id; ij < iprim*jprim; ij += threads) {
        int ip = ij / jprim;
        int jp = ij % jprim;
        double ai = env[expi+ip];
        double aj = env[expj+jp];
        double aij = ai + aj;
        double theta_ij = ai * aj / aij;
        double rr_ij = xjxi*xjxi + yjyi*yjyi + zjzi*zjzi;
        double Kab = exp(-theta_ij * rr_ij);
        cicj_cache[ij] = ci[ip] * cj[jp] * Kab;
    }
    __syncthreads();

    int *ao_loc = envs.ao_loc;
    int nao = ao_loc[nbas];
    double *dm = jk.dm;
    double v_ix = 0;
    double v_iy = 0;
    double v_iz = 0;
    double v_jx = 0;
    double v_jy = 0;
    double v_jz = 0;
    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += nsq_per_block) {
        // another thread of this quartet may still read the previous task's dd_cache
        __syncthreads();
        uint32_t bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (ish*nbas+jsh == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        int i0 = ao_loc[ish];
        int j0 = ao_loc[jsh];
        int k0 = ao_loc[ksh];
        int l0 = ao_loc[lsh];
        int expk = bas[ksh*BAS_SLOTS+PTR_EXP];
        int expl = bas[lsh*BAS_SLOTS+PTR_EXP];
        int ck = bas[ksh*BAS_SLOTS+PTR_COEFF];
        int cl = bas[lsh*BAS_SLOTS+PTR_COEFF];
        int rk = bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        int rl = bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        double xlxk = env[rl+0] - env[rk+0];
        double ylyk = env[rl+1] - env[rk+1];
        double zlzk = env[rl+2] - env[rk+2];
        if (gout_id == 0) {
            rlrk[0] = xlxk;
            rlrk[64] = ylyk;
            rlrk[2*64] = zlzk;
        }
        double v_kx = 0;
        double v_ky = 0;
        double v_kz = 0;
        double v_lx = 0;
        double v_ly = 0;
        double v_lz = 0;
        int do_j = jk.j_factor != 0.;
        int do_k = jk.k_factor != 0.;
        if (jk.n_dm == 1) {
            for (int n = gout_id; n < 90; n+=4) {
                int i = n % 10;
                int j = n / 10 % 1;
                int k = n / 10 % 3;
                int l = n / 30;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _li = _l*nao+_i;
                int _ki = _k*nao+_i;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += jk.k_factor * (dm[_jk] * dm[_li] + dm[_jl] * dm[_ki]);
                }
                if (do_j) {
                    dd += jk.j_factor * dm[_ji] * dm[_lk];
                }
                dd_cache[n*64] = fac_sym * dd;
            }
        } else {
            double *dmb = dm + nao * nao;
            for (int n = gout_id; n < 90; n+=4) {
                int i = n % 10;
                int j = n / 10 % 1;
                int k = n / 10 % 3;
                int l = n / 30;
                int _i = i + i0;
                int _j = j + j0;
                int _k = k + k0;
                int _l = l + l0;
                int _jl = _j*nao+_l;
                int _jk = _j*nao+_k;
                int _li = _l*nao+_i;
                int _ki = _k*nao+_i;
                int _ji = _j*nao+_i;
                int _lk = _l*nao+_k;
                double dd = 0;
                if (do_k) {
                    dd += jk.k_factor * (dm [_jk] * dm [_li] + dm [_jl] * dm [_ki] +
                                         dmb[_jk] * dmb[_li] + dmb[_jl] * dmb[_ki]);
                }
                if (do_j) {
                    dd += jk.j_factor * (dm[_ji] + dmb[_ji]) * (dm[_lk] + dmb[_lk]);
                }
                dd_cache[n*64] = fac_sym * dd;
            }
        }
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            int kp = klp / lprim;
            int lp = klp % lprim;
            double ak = env[expk+kp];
            double al = env[expl+lp];
            double ak2 = ak * 2;
            double al2 = al * 2;
            double akl = ak + al;
            double al_akl = al / akl;
            double theta_kl = ak * al_akl;
            __syncthreads();
            if (gout_id == 0) {
                double Kcd = exp(-theta_kl * (xlxk*xlxk+ylyk*ylyk+zlzk*zlzk));
                double ckcl = env[ck+kp] * env[cl+lp] * Kcd;
                gx[0] = ckcl;
            }
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                if (fabs(cicj_cache[ijp]) < PRIM_CUTOFF) continue;
                int ip = ijp / jprim;
                int jp = ijp % jprim;
                double ai = env[expi+ip];
                double aj = env[expj+jp];
                double ai2 = ai * 2;
                double aj2 = aj * 2;
                double aij = ai + aj;
                double aj_aij = aj / aij;
                double xij = ri[0] + rjri[0] * aj_aij;
                double yij = ri[1] + rjri[1] * aj_aij;
                double zij = ri[2] + rjri[2] * aj_aij;
                double xkl = env[rk+0] + xlxk * al_akl;
                double ykl = env[rk+1] + ylyk * al_akl;
                double zkl = env[rk+2] + zlzk * al_akl;
                double xpq = xij - xkl;
                double ypq = yij - ykl;
                double zpq = zij - zkl;
                double theta = aij * akl / (aij + akl);
                double rr = xpq * xpq + ypq * ypq + zpq * zpq;
                __syncthreads();
                if (gout_id == 0) {
                    Rpq[0] = xpq;
                    Rpq[64] = ypq;
                    Rpq[2*64] = zpq;
                    double cicj = cicj_cache[ijp];
                    gx[30*64] = cicj / (aij*akl*sqrt(aij+akl));
                }
                rys_roots_for_k(nroots, theta, rr, rw, jk.omega, jk.lr_factor, jk.sr_factor, nsq_per_block, 4, gout_id);
                for (int irys = 0; irys < nroots; ++irys) {
                    __syncthreads();
                    double s0, s1, s2;
                    double rt = rw[irys*128];
                    double rt_aa = rt / (aij + akl);
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5/aij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    double b01 = .5/akl * (1 - rt_akl);
                    for (int n = gout_id; n < 3; n += 4) {
                        if (n == 2) {
                            gx[3840] = rw[irys*128+64];
                        }
                        double *_gx = gx + n * 1920;
                        double xjxi = rjri[n];
                        double Rpa = xjxi * aj_aij;
                        double c0x = Rpa - rt_aij * Rpq[n*64];
                        s0 = _gx[0];
                        s1 = c0x * s0;
                        _gx[64] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[128] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[192] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 3 * b10 * s0;
                        _gx[256] = s2;
                        double xlxk = rlrk[n*64];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*64];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[320] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        _gx[640] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        _gx[960] = s2;
                        s0 = _gx[64];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[384] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 1 * b00 * _gx[320];
                        _gx[704] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 1 * b00 * _gx[640];
                        _gx[1024] = s2;
                        s0 = _gx[128];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[64];
                        _gx[448] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 2 * b00 * _gx[384];
                        _gx[768] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 2 * b00 * _gx[704];
                        _gx[1088] = s2;
                        s0 = _gx[192];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[128];
                        _gx[512] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 3 * b00 * _gx[448];
                        _gx[832] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 3 * b00 * _gx[768];
                        _gx[1152] = s2;
                        s0 = _gx[256];
                        s1 = cpx * s0;
                        s1 += 4 * b00 * _gx[192];
                        _gx[576] = s1;
                        s2 = cpx*s1 + 1 * b01 *s0;
                        s2 += 4 * b00 * _gx[512];
                        _gx[896] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx*s1 + 2 * b01 *s0;
                        s2 += 4 * b00 * _gx[832];
                        _gx[1216] = s2;
                        s1 = _gx[960];
                        s0 = _gx[640];
                        _gx[1600] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[320];
                        _gx[1280] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[0];
                        _gx[960] = s1 - xlxk * s0;
                        s1 = s0;
                        s1 = _gx[1024];
                        s0 = _gx[704];
                        _gx[1664] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[384];
                        _gx[1344] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[64];
                        _gx[1024] = s1 - xlxk * s0;
                        s1 = s0;
                        s1 = _gx[1088];
                        s0 = _gx[768];
                        _gx[1728] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[448];
                        _gx[1408] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[128];
                        _gx[1088] = s1 - xlxk * s0;
                        s1 = s0;
                        s1 = _gx[1152];
                        s0 = _gx[832];
                        _gx[1792] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[512];
                        _gx[1472] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[192];
                        _gx[1152] = s1 - xlxk * s0;
                        s1 = s0;
                        s1 = _gx[1216];
                        s0 = _gx[896];
                        _gx[1856] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[576];
                        _gx[1536] = s1 - xlxk * s0;
                        s1 = s0;
                        s0 = _gx[256];
                        _gx[1216] = s1 - xlxk * s0;
                        s1 = s0;
                    }
                    __syncthreads();
                    double s;
                    volatile double *vgx = gx;
                    switch (gout_id) {
                    case 0:
                    s = dd_cache[2944] * (vgx[3392] * vgx[3840]);
                    s += dd_cache[3008] * (vgx[3328] * vgx[3904]);
                    s += dd_cache[3072] * (vgx[3264] * vgx[3968]);
                    s += dd_cache[3136] * (vgx[3200] * vgx[4032]);
                    s += dd_cache[3584] * (vgx[3072] * vgx[4160]);
                    s += dd_cache[3648] * (vgx[3008] * vgx[4224]);
                    s += dd_cache[3712] * (vgx[2944] * vgx[4288]);
                    s += dd_cache[3776] * (vgx[2880] * vgx[4352]);
                    s += dd_cache[4864] * (vgx[2432] * vgx[4800]);
                    s += dd_cache[4928] * (vgx[2368] * vgx[4864]);
                    s += dd_cache[4992] * (vgx[2304] * vgx[4928]);
                    s += dd_cache[5056] * (vgx[2240] * vgx[4992]);
                    s += dd_cache[5504] * (vgx[2112] * vgx[5120]);
                    s += dd_cache[5568] * (vgx[2048] * vgx[5184]);
                    s += dd_cache[5632] * (vgx[1984] * vgx[5248]);
                    s += dd_cache[5696] * (vgx[1920] * vgx[5312]);
                    v_ix += (ai2 * vgx[64]) * s;
                    v_kx += (ak2 * vgx[320]) * s;
                    v_lx += (al2 * (vgx[320] - xlxk * vgx[0])) * s;
                    s = dd_cache[1024] * (vgx[2432] * vgx[3840]);
                    s += dd_cache[1088] * (vgx[2368] * vgx[3904]);
                    s += dd_cache[1152] * (vgx[2304] * vgx[3968]);
                    s += dd_cache[1216] * (vgx[2240] * vgx[4032]);
                    s += dd_cache[1664] * (vgx[2112] * vgx[4160]);
                    s += dd_cache[1728] * (vgx[2048] * vgx[4224]);
                    s += dd_cache[1792] * (vgx[1984] * vgx[4288]);
                    s += dd_cache[1856] * (vgx[1920] * vgx[4352]);
                    v_ix += (ai2 * vgx[1024]) * s;
                    v_kx += (ak2 * vgx[1280]) * s;
                    v_lx += (al2 * (vgx[1280] - xlxk * vgx[960]) - 1 * vgx[0]) * s;
                    s = dd_cache[2304] * (vgx[3072] * vgx[3840]);
                    s += dd_cache[2368] * (vgx[3008] * vgx[3904]);
                    s += dd_cache[2432] * (vgx[2944] * vgx[3968]);
                    s += dd_cache[2496] * (vgx[2880] * vgx[4032]);
                    s += dd_cache[4224] * (vgx[2112] * vgx[4800]);
                    s += dd_cache[4288] * (vgx[2048] * vgx[4864]);
                    s += dd_cache[4352] * (vgx[1984] * vgx[4928]);
                    s += dd_cache[4416] * (vgx[1920] * vgx[4992]);
                    v_ix += (ai2 * vgx[384]) * s;
                    v_kx += (ak2 * vgx[640] - 1 * vgx[0]) * s;
                    v_lx += (al2 * (vgx[640] - xlxk * vgx[320])) * s;
                    s = dd_cache[0] * (vgx[1472] * vgx[3840]);
                    s += dd_cache[128] * (vgx[1408] * vgx[3904]);
                    s += dd_cache[320] * (vgx[1344] * vgx[3968]);
                    s += dd_cache[576] * (vgx[1280] * vgx[4032]);
                    s += dd_cache[1280] * (vgx[1152] * vgx[4160]);
                    s += dd_cache[1408] * (vgx[1088] * vgx[4224]);
                    s += dd_cache[1600] * (vgx[1024] * vgx[4288]);
                    s += dd_cache[1856] * (vgx[960] * vgx[4352]);
                    s += dd_cache[3840] * (vgx[512] * vgx[4800]);
                    s += dd_cache[3968] * (vgx[448] * vgx[4864]);
                    s += dd_cache[4160] * (vgx[384] * vgx[4928]);
                    s += dd_cache[4416] * (vgx[320] * vgx[4992]);
                    s += dd_cache[5120] * (vgx[192] * vgx[5120]);
                    s += dd_cache[5248] * (vgx[128] * vgx[5184]);
                    s += dd_cache[5440] * (vgx[64] * vgx[5248]);
                    s += dd_cache[5696] * (vgx[0] * vgx[5312]);
                    v_iy += (ai2 * vgx[1984]) * s;
                    v_ky += (ak2 * vgx[2240]) * s;
                    v_ly += (al2 * (vgx[2240] - ylyk * vgx[1920])) * s;
                    s = dd_cache[1920] * (vgx[512] * vgx[3840]);
                    s += dd_cache[2048] * (vgx[448] * vgx[3904]);
                    s += dd_cache[2240] * (vgx[384] * vgx[3968]);
                    s += dd_cache[2496] * (vgx[320] * vgx[4032]);
                    s += dd_cache[3200] * (vgx[192] * vgx[4160]);
                    s += dd_cache[3328] * (vgx[128] * vgx[4224]);
                    s += dd_cache[3520] * (vgx[64] * vgx[4288]);
                    s += dd_cache[3776] * (vgx[0] * vgx[4352]);
                    v_iy += (ai2 * vgx[2944]) * s;
                    v_ky += (ak2 * vgx[3200]) * s;
                    v_ly += (al2 * (vgx[3200] - ylyk * vgx[2880]) - 1 * vgx[1920]) * s;
                    s = dd_cache[640] * (vgx[1152] * vgx[3840]);
                    s += dd_cache[768] * (vgx[1088] * vgx[3904]);
                    s += dd_cache[960] * (vgx[1024] * vgx[3968]);
                    s += dd_cache[1216] * (vgx[960] * vgx[4032]);
                    s += dd_cache[4480] * (vgx[192] * vgx[4800]);
                    s += dd_cache[4608] * (vgx[128] * vgx[4864]);
                    s += dd_cache[4800] * (vgx[64] * vgx[4928]);
                    s += dd_cache[5056] * (vgx[0] * vgx[4992]);
                    v_iy += (ai2 * vgx[2304]) * s;
                    v_ky += (ak2 * vgx[2560] - 1 * vgx[1920]) * s;
                    v_ly += (al2 * (vgx[2560] - ylyk * vgx[2240])) * s;
                    s = dd_cache[0] * (vgx[1472] * vgx[1920]);
                    s += dd_cache[64] * (vgx[1408] * vgx[1984]);
                    s += dd_cache[192] * (vgx[1344] * vgx[2048]);
