                    v_lx += (al2 * (vgx[768] - xlxk * vgx[448])) * s;
                    s = dd_cache[1984] * (vgx[128] * vgx[2560]);
                    s += dd_cache[2176] * (vgx[64] * vgx[2624]);
                    s += dd_cache[2432] * (vgx[0] * vgx[2688]);
