                    v_ky += (ak2 * vgx[2304] - 2 * vgx[1664]) * s;
                    v_ly += (al2 * (vgx[2304] - ylyk * vgx[1984])) * s;
                    s = dd_cache[192] * (vgx[704] * vgx[2560]);
