                    s += dd_cache[3392] * (vgx[64] * vgx[3200]);
                    s += dd_cache[3648] * (vgx[0] * vgx[3264]);
                    v_iy += (ai2 * vgx[1472] - 2 * vgx[1344]) * s;
                    v_ky += (ak2 * vgx[1728]) * s;
                    v_ly += (al2 * (vgx[1728] - ylyk * vgx[1408])) * s;
                    s = dd_cache[832] * (vgx[384] * vgx[2560]);
                    s += dd_cache[1088] * (vgx[320] * vgx[2624]);
                    s += dd_cache[2752] * (vgx[64] * vgx[2880]);
                    s += dd_cache[3008] * (vgx[0] * vgx[2944]);
                    v_iy += (ai2 * vgx[1792] - 2 * vgx[1664]) * s;
                    v_ky += (ak2 * vgx[2048] - 1 * vgx[1408]) * s;
                    v_ly += (al2 * (vgx[2048] - ylyk * vgx[1728])) * s;
                    s = dd_cache[3328] * (vgx[128] * vgx[1280]);
                    s += dd_cache[3456] * (vgx[64] * vgx[1344]);
                    s += dd_cache[3648] * (vgx[0] * vgx[1408]);
                    v_iz += (ai2 * vgx[3328] - 1 * vgx[3200]) * s;
                    v_kz += (ak2 * vgx[3584] - 2 * vgx[2944]) * s;
                    v_lz += (al2 * (vgx[3584] - zlzk * vgx[3264])) * s;
                    s = dd_cache[320] * (vgx[704] * vgx[1280]);
                    s += dd_cache[512] * (vgx[640] * vgx[1344]);
                    s += dd_cache[960] * (vgx[384] * vgx[1600]);
                    s += dd_cache[1152] * (vgx[320] * vgx[1664]);
                    s += dd_cache[2240] * (vgx[64] * vgx[1920]);
                    s += dd_cache[2432] * (vgx[0] * vgx[1984]);
                    v_iz += (ai2 * vgx[2752] - 2 * vgx[2624]) * s;
                    v_kz += (ak2 * vgx[3008]) * s;
                    v_lz += (al2 * (vgx[3008] - zlzk * vgx[2688])) * s;
                    s = dd_cache[1600] * (vgx[384] * vgx[1280]);
                    s += dd_cache[1792] * (vgx[320] * vgx[1344]);
                    s += dd_cache[2880] * (vgx[64] * vgx[1600]);
                    s += dd_cache[3072] * (vgx[0] * vgx[1664]);
                    v_iz += (ai2 * vgx[3072] - 2 * vgx[2944]) * s;
                    v_kz += (ak2 * vgx[3328] - 1 * vgx[2688]) * s;
                    v_lz += (al2 * (vgx[3328] - zlzk * vgx[3008])) * s;
                    break;
                    case 3:
                    s = dd_cache[64] * (vgx[1344] * vgx[2560]);
                    s += dd_cache[128] * (vgx[1280] * vgx[2624]);
                    v_ix += (ai2 * vgx[832] - 2 * vgx[704]) * s;
                    v_kx += (ak2 * vgx[1088] - 2 * vgx[448]) * s;
                    v_lx += (al2 * (vgx[1088] - xlxk * vgx[768])) * s;
                    s = dd_cache[1920] * (vgx[1920] * vgx[2560]);
                    s += dd_cache[2560] * (vgx[1600] * vgx[2880]);
