                    s = dd_cache[640] * (vgx[1600] * vgx[2560]);
                    s += dd_cache[1280] * (vgx[1280] * vgx[2880]);
                    v_ix += (ai2 * vgx[576] - 3 * vgx[448]) * s;
                    v_kx += (ak2 * vgx[832] - 1 * vgx[192]) * s;
                    v_lx += (al2 * (vgx[832] - xlxk * vgx[512])) * s;
