                    s += dd_cache[2368] * (vgx[0] * vgx[2624]);
                    v_iy += (ai2 * vgx[2112] - 2 * vgx[1984]) * s;
                    v_ky += (ak2 * vgx[2368] - 2 * vgx[1728]) * s;
                    v_ly += (al2 * (vgx[2368] - ylyk * vgx[2048])) * s;
                    s = dd_cache[384] * (vgx[640] * vgx[2560]);
                    s += dd_cache[1664] * (vgx[320] * vgx[2880]);
                    s += dd_cache[3584] * (vgx[0] * vgx[3200]);
                    v_iy += (ai2 * vgx[1536] - 3 * vgx[1408]) * s;
                    v_ky += (ak2 * vgx[1792]) * s;
                    v_ly += (al2 * (vgx[1792] - ylyk * vgx[1472])) * s;
                    s = dd_cache[1024] * (vgx[320] * vgx[2560]);
                    s += dd_cache[2944] * (vgx[0] * vgx[2880]);
                    v_iy += (ai2 * vgx[1856] - 3 * vgx[1728]) * s;
                    v_ky += (ak2 * vgx[2112] - 1 * vgx[1472]) * s;
                    v_ly += (al2 * (vgx[2112] - ylyk * vgx[1792])) * s;
                    s = dd_cache[2304] * (vgx[0] * vgx[2560]);
                    v_iy += (ai2 * vgx[2176] - 3 * vgx[2048]) * s;
                    v_ky += (ak2 * vgx[2432] - 2 * vgx[1792]) * s;
                    v_ly += (al2 * (vgx[2432] - ylyk * vgx[2112])) * s;
                    s = dd_cache[3520] * (vgx[64] * vgx[1280]);
                    s += dd_cache[3712] * (vgx[0] * vgx[1344]);
                    v_iz += (ai2 * vgx[3392] - 2 * vgx[3264]) * s;
                    v_kz += (ak2 * vgx[3648] - 2 * vgx[3008]) * s;
                    v_lz += (al2 * (vgx[3648] - zlzk * vgx[3328])) * s;
                    s = dd_cache[576] * (vgx[640] * vgx[1280]);
                    s += dd_cache[1216] * (vgx[320] * vgx[1600]);
                    s += dd_cache[2496] * (vgx[0] * vgx[1920]);
                    v_iz += (ai2 * vgx[2816] - 3 * vgx[2688]) * s;
                    v_kz += (ak2 * vgx[3072]) * s;
                    v_lz += (al2 * (vgx[3072] - zlzk * vgx[2752])) * s;
                    s = dd_cache[1856] * (vgx[320] * vgx[1280]);
                    s += dd_cache[3136] * (vgx[0] * vgx[1600]);
                    v_iz += (ai2 * vgx[3136] - 3 * vgx[3008]) * s;
                    v_kz += (ak2 * vgx[3392] - 1 * vgx[2752]) * s;
                    v_lz += (al2 * (vgx[3392] - zlzk * vgx[3072])) * s;
                    s = dd_cache[3776] * (vgx[0] * vgx[1280]);
                    v_iz += (ai2 * vgx[3456] - 3 * vgx[3328]) * s;
                    v_kz += (ak2 * vgx[3712] - 2 * vgx[3072]) * s;
                    v_lz += (al2 * (vgx[3712] - zlzk * vgx[3392])) * s;
                    break;
                    }
                }
            }
        }
        if (task_id >= ntasks) {
            break;
        }
        int ka = bas[ksh*BAS_SLOTS+ATOM_OF];
        int la = bas[lsh*BAS_SLOTS+ATOM_OF];
        double *ejk = jk.ejk;
        atomicAdd(ejk+ka*3+0, v_kx);
        atomicAdd(ejk+ka*3+1, v_ky);
        atomicAdd(ejk+ka*3+2, v_kz);
        atomicAdd(ejk+la*3+0, v_lx);
        atomicAdd(ejk+la*3+1, v_ly);
        atomicAdd(ejk+la*3+2, v_lz);
        // translational invariance: j's derivative is minus the sum of the other three centers'
        v_jx += v_kx + v_lx;
        v_jy += v_ky + v_ly;
        v_jz += v_kz + v_lz;
    }
    int ia = bas[ish*BAS_SLOTS+ATOM_OF];
    int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
    double *ejk = jk.ejk;
    atomicAdd(ejk+ia*3+0, v_ix);
    atomicAdd(ejk+ia*3+1, v_iy);
    atomicAdd(ejk+ia*3+2, v_iz);
    atomicAdd(ejk+ja*3+0, -(v_ix + v_jx));
    atomicAdd(ejk+ja*3+1, -(v_iy + v_jy));
    atomicAdd(ejk+ja*3+2, -(v_iz + v_jz));
}
}
// (fs|ss): 10 outputs, one thread per quartet, g_size 10
__global__ static
void rys_ejk_ip1_gen_3000(JKENERGY_KERNEL_ARGS)
{
    JKENERGY_KERNEL_SETUP();
    constexpr int nsq_per_block = 128;
    constexpr int gout_stride = 1;
    int t_id = gout_id * nsq_per_block + sq_id;
    int threads = nsq_per_block * gout_stride;
    int nbas = envs.nbas;
    int *bas = envs.bas;
    double *env = envs.env;
    int iprim = bounds.iprim;
    int jprim = bounds.jprim;
    int kprim = bounds.kprim;
    int lprim = bounds.lprim;
    int nroots = bounds.nroots;
    double *rw = shared_memory + sq_id;
    double *cicj_cache = shared_memory + nsq_per_block * (nroots*2);

    uint32_t *bas_kl_idx = pool + worker_id * QUEUE_DEPTH;
while (1) {
    __syncthreads();
    if (t_id == 0) {
        int task_id = atomicAdd(head, 1);
        int batch_kl = task_id / bounds.npairs_ij;
        pair_ij = task_id - bounds.npairs_ij * batch_kl;
        pair_kl0 = batch_kl * (QUEUE_DEPTH - 512);
        uint32_t bas_ij = bounds.pair_ij_mapping[pair_ij];
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    if (pair_kl0 >= bounds.npairs_kl) {
        break;
    }
    if (jk.lr_factor != 0) {
        _fill_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                        q_cond_ij, q_cond_kl,
                        (int *)shared_memory, jk, envs, bounds);
    } else {
        _fill_sr_ejk_tasks(ntasks, pair_kl0, bas_kl_idx, pair_ij, ish, jsh,
                           q_cond_ij, q_cond_kl,
                           s_cond_ij, s_cond_kl, diffuse_exps,
                           (int *)shared_memory, jk, envs, bounds);
    }
    if (ntasks == 0) {
        continue;
    }
    if (t_id == 0) {
        expi = bas[ish*BAS_SLOTS+PTR_EXP];
        expj = bas[jsh*BAS_SLOTS+PTR_EXP];
    }
    __syncthreads();
    if (t_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[t_id] = env[ri_ptr+t_id];
        rjri[t_id] = env[rj_ptr+t_id] - ri[t_id];
    }
    __syncthreads();
    double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
    double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
    double xjxi = rjri[0];
    double yjyi = rjri[1];
    double zjzi = rjri[2];
    for (int ij = t_id; ij < iprim*jprim; ij += threads) {
        int ip = ij / jprim;
        int jp = ij % jprim;
        double ai = env[expi+ip];
        double aj = env[expj+jp];
        double aij = ai + aj;
        double theta_ij = ai * aj / aij;
        double rr_ij = xjxi*xjxi + yjyi*yjyi + zjzi*zjzi;
        double Kab = exp(-theta_ij * rr_ij);
        cicj_cache[ij] = ci[ip] * cj[jp] * Kab;
    }
    __syncthreads();

    int *ao_loc = envs.ao_loc;
    int nao = ao_loc[nbas];
    double *dm = jk.dm;
    double v_ix = 0;
    double v_iy = 0;
    double v_iz = 0;
    double v_jx = 0;
    double v_jy = 0;
    double v_jz = 0;
    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += nsq_per_block) {
        if (task_id >= ntasks) break;
        uint32_t bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (ish*nbas+jsh == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        int i0 = ao_loc[ish];
        int j0 = ao_loc[jsh];
        int k0 = ao_loc[ksh];
        int l0 = ao_loc[lsh];
        int expk = bas[ksh*BAS_SLOTS+PTR_EXP];
        int expl = bas[lsh*BAS_SLOTS+PTR_EXP];
        int ck = bas[ksh*BAS_SLOTS+PTR_COEFF];
        int cl = bas[lsh*BAS_SLOTS+PTR_COEFF];
        int rk = bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        int rl = bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        double xlxk = env[rl+0] - env[rk+0];
        double ylyk = env[rl+1] - env[rk+1];
        double zlzk = env[rl+2] - env[rk+2];
        double v_kx = 0;
        double v_ky = 0;
        double v_kz = 0;
        double v_lx = 0;
        double v_ly = 0;
        double v_lz = 0;
        int do_j = jk.j_factor != 0.;
        int do_k = jk.k_factor != 0.;
        double dd[10];
        if (jk.n_dm == 1) {
            double *dmb = dm;
            dd[0] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+0)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+0)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[1] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+1)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+1)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[2] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+2)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+2)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[3] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+3)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+3)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+3)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[4] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+4)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+4)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+4)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[5] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+5)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+5)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+5)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[6] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+6)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+6)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+6)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[7] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+7)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+7)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+7)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[8] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+8)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+8)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+8)] * dm[(l0+0)*nao+(k0+0)] : 0.));
            dd[9] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+9)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+9)]) : 0.) + (do_j ? jk.j_factor * dm[(j0+0)*nao+(i0+9)] * dm[(l0+0)*nao+(k0+0)] : 0.));
        } else {
            double *dmb = dm + nao * nao;
            dd[0] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+0)] + dmb[(j0+0)*nao+(k0+0)] * dmb[(l0+0)*nao+(i0+0)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+0)*nao+(i0+0)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+0)] + dmb[(j0+0)*nao+(i0+0)]) * (dm[(l0+0)*nao+(k0+0)] + dmb[(l0+0)*nao+(k0+0)]) : 0.));
            dd[1] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+1)] + dmb[(j0+0)*nao+(k0+0)] * dmb[(l0+0)*nao+(i0+1)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+0)*nao+(i0+1)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+1)] + dmb[(j0+0)*nao+(i0+1)]) * (dm[(l0+0)*nao+(k0+0)] + dmb[(l0+0)*nao+(k0+0)]) : 0.));
            dd[2] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+2)] + dmb[(j0+0)*nao+(k0+0)] * dmb[(l0+0)*nao+(i0+2)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+0)*nao+(i0+2)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+2)] + dmb[(j0+0)*nao+(i0+2)]) * (dm[(l0+0)*nao+(k0+0)] + dmb[(l0+0)*nao+(k0+0)]) : 0.));
            dd[3] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+3)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+3)] + dmb[(j0+0)*nao+(k0+0)] * dmb[(l0+0)*nao+(i0+3)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+0)*nao+(i0+3)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+3)] + dmb[(j0+0)*nao+(i0+3)]) * (dm[(l0+0)*nao+(k0+0)] + dmb[(l0+0)*nao+(k0+0)]) : 0.));
            dd[4] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+4)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+4)] + dmb[(j0+0)*nao+(k0+0)] * dmb[(l0+0)*nao+(i0+4)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+0)*nao+(i0+4)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+4)] + dmb[(j0+0)*nao+(i0+4)]) * (dm[(l0+0)*nao+(k0+0)] + dmb[(l0+0)*nao+(k0+0)]) : 0.));
            dd[5] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+5)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+5)] + dmb[(j0+0)*nao+(k0+0)] * dmb[(l0+0)*nao+(i0+5)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+0)*nao+(i0+5)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+5)] + dmb[(j0+0)*nao+(i0+5)]) * (dm[(l0+0)*nao+(k0+0)] + dmb[(l0+0)*nao+(k0+0)]) : 0.));
            dd[6] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+6)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+6)] + dmb[(j0+0)*nao+(k0+0)] * dmb[(l0+0)*nao+(i0+6)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+0)*nao+(i0+6)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+6)] + dmb[(j0+0)*nao+(i0+6)]) * (dm[(l0+0)*nao+(k0+0)] + dmb[(l0+0)*nao+(k0+0)]) : 0.));
            dd[7] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+7)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+7)] + dmb[(j0+0)*nao+(k0+0)] * dmb[(l0+0)*nao+(i0+7)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+0)*nao+(i0+7)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+7)] + dmb[(j0+0)*nao+(i0+7)]) * (dm[(l0+0)*nao+(k0+0)] + dmb[(l0+0)*nao+(k0+0)]) : 0.));
            dd[8] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+8)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+8)] + dmb[(j0+0)*nao+(k0+0)] * dmb[(l0+0)*nao+(i0+8)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+0)*nao+(i0+8)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+8)] + dmb[(j0+0)*nao+(i0+8)]) * (dm[(l0+0)*nao+(k0+0)] + dmb[(l0+0)*nao+(k0+0)]) : 0.));
            dd[9] = fac_sym * ((do_k ? jk.k_factor * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+9)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+9)] + dmb[(j0+0)*nao+(k0+0)] * dmb[(l0+0)*nao+(i0+9)] + dmb[(j0+0)*nao+(l0+0)] * dmb[(k0+0)*nao+(i0+9)]) : 0.) + (do_j ? jk.j_factor * (dm[(j0+0)*nao+(i0+9)] + dmb[(j0+0)*nao+(i0+9)]) * (dm[(l0+0)*nao+(k0+0)] + dmb[(l0+0)*nao+(k0+0)]) : 0.));
        }
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            int kp = klp / lprim;
            int lp = klp % lprim;
            double ak = env[expk+kp];
            double al = env[expl+lp];
            double ak2 = ak * 2;
            double al2 = al * 2;
            double akl = ak + al;
            double al_akl = al / akl;
            double theta_kl = ak * al_akl;
            double Kcd = exp(-theta_kl * (xlxk*xlxk+ylyk*ylyk+zlzk*zlzk));
            double ckcl = env[ck+kp] * env[cl+lp] * Kcd;
            if (fabs(ckcl) < PRIM_CUTOFF) continue;
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                int ip = ijp / jprim;
                int jp = ijp % jprim;
                double ai = env[expi+ip];
                double aj = env[expj+jp];
                double ai2 = ai * 2;
                double aj2 = aj * 2;
                double aij = ai + aj;
                double aj_aij = aj / aij;
                double cicj = cicj_cache[ijp];
                if (fabs(cicj) < PRIM_CUTOFF) continue;
                double fac = cicj * ckcl / (aij*akl*sqrt(aij+akl));
                double xij = ri[0] + rjri[0] * aj_aij;
                double yij = ri[1] + rjri[1] * aj_aij;
                double zij = ri[2] + rjri[2] * aj_aij;
                double xkl = env[rk+0] + xlxk * al_akl;
                double ykl = env[rk+1] + ylyk * al_akl;
                double zkl = env[rk+2] + zlzk * al_akl;
                double Rpq[3] = {xij - xkl, yij - ykl, zij - zkl};
                double rlrk[3] = {xlxk, ylyk, zlzk};
                double rr = Rpq[0]*Rpq[0] + Rpq[1]*Rpq[1] + Rpq[2]*Rpq[2];
                double theta = aij * akl / (aij + akl);
                rys_roots_for_k(nroots, theta, rr, rw, jk.omega, jk.lr_factor, jk.sr_factor, nsq_per_block, 1, 0);
                for (int irys = 0; irys < nroots; ++irys) {
                    double s0, s1, s2;
                    double rt = rw[irys*256];
                    double rt_aa = rt / (aij + akl);
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5/aij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    double g[30];
                    g[0] = 1.;
                    g[10] = 1.;
                    g[20] = rw[irys*256+128] * fac;
                    {
                        constexpr int n = 0;
                        double *_gx = g + 0;
                        double xjxi = rjri[n];
                        double Rpa = xjxi * aj_aij;
                        double c0x = Rpa - rt_aij * Rpq[n];
                        s0 = _gx[0];
                        s1 = c0x * s0;
                        _gx[1] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[2] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[3] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 3 * b10 * s0;
                        _gx[4] = s2;
                        double xlxk = rlrk[n*1];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*1];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[5] = s1;
                        s0 = _gx[1];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[6] = s1;
                        s0 = _gx[2];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[1];
                        _gx[7] = s1;
                        s0 = _gx[3];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[2];
                        _gx[8] = s1;
                        s0 = _gx[4];
                        s1 = cpx * s0;
                        s1 += 4 * b00 * _gx[3];
                        _gx[9] = s1;
                    }
                    {
                        constexpr int n = 1;
                        double *_gx = g + 10;
                        double xjxi = rjri[n];
                        double Rpa = xjxi * aj_aij;
                        double c0x = Rpa - rt_aij * Rpq[n];
                        s0 = _gx[0];
                        s1 = c0x * s0;
                        _gx[1] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[2] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[3] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 3 * b10 * s0;
                        _gx[4] = s2;
                        double xlxk = rlrk[n*1];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*1];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[5] = s1;
                        s0 = _gx[1];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[6] = s1;
                        s0 = _gx[2];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[1];
                        _gx[7] = s1;
                        s0 = _gx[3];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[2];
                        _gx[8] = s1;
                        s0 = _gx[4];
                        s1 = cpx * s0;
                        s1 += 4 * b00 * _gx[3];
                        _gx[9] = s1;
                    }
                    {
                        constexpr int n = 2;
                        double *_gx = g + 20;
                        double xjxi = rjri[n];
                        double Rpa = xjxi * aj_aij;
                        double c0x = Rpa - rt_aij * Rpq[n];
                        s0 = _gx[0];
                        s1 = c0x * s0;
                        _gx[1] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[2] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[3] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 3 * b10 * s0;
                        _gx[4] = s2;
                        double xlxk = rlrk[n*1];
                        double Rqc = xlxk * al_akl;
                        double cpx = Rqc + rt_akl * Rpq[n*1];
                        s0 = _gx[0];
                        s1 = cpx * s0;
                        _gx[5] = s1;
                        s0 = _gx[1];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0];
                        _gx[6] = s1;
                        s0 = _gx[2];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[1];
                        _gx[7] = s1;
                        s0 = _gx[3];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[2];
                        _gx[8] = s1;
                        s0 = _gx[4];
                        s1 = cpx * s0;
                        s1 += 4 * b00 * _gx[3];
                        _gx[9] = s1;
                    }
                    double s;
                    s = dd[6] * (g[13] * g[20]);
                    s += dd[7] * (g[12] * g[21]);
                    s += dd[8] * (g[11] * g[22]);
                    s += dd[9] * (g[10] * g[23]);
                    v_ix += (ai2 * g[1]) * s;
                    v_kx += (ak2 * g[5]) * s;
                    v_lx += (al2 * (g[5] - xlxk * g[0])) * s;
                    s = dd[3] * (g[12] * g[20]);
                    s += dd[4] * (g[11] * g[21]);
                    s += dd[5] * (g[10] * g[22]);
                    v_ix += (ai2 * g[2] - 1 * g[0]) * s;
                    v_kx += (ak2 * g[6]) * s;
                    v_lx += (al2 * (g[6] - xlxk * g[1])) * s;
                    s = dd[1] * (g[11] * g[20]);
                    s += dd[2] * (g[10] * g[21]);
                    v_ix += (ai2 * g[3] - 2 * g[1]) * s;
                    v_kx += (ak2 * g[7]) * s;
                    v_lx += (al2 * (g[7] - xlxk * g[2])) * s;
                    s = dd[0] * (g[10] * g[20]);
                    v_ix += (ai2 * g[4] - 3 * g[2]) * s;
                    v_kx += (ak2 * g[8]) * s;
                    v_lx += (al2 * (g[8] - xlxk * g[3])) * s;
                    s = dd[0] * (g[3] * g[20]);
                    s += dd[2] * (g[2] * g[21]);
                    s += dd[5] * (g[1] * g[22]);
                    s += dd[9] * (g[0] * g[23]);
                    v_iy += (ai2 * g[11]) * s;
                    v_ky += (ak2 * g[15]) * s;
                    v_ly += (al2 * (g[15] - ylyk * g[10])) * s;
                    s = dd[1] * (g[2] * g[20]);
                    s += dd[4] * (g[1] * g[21]);
                    s += dd[8] * (g[0] * g[22]);
                    v_iy += (ai2 * g[12] - 1 * g[10]) * s;
                    v_ky += (ak2 * g[16]) * s;
                    v_ly += (al2 * (g[16] - ylyk * g[11])) * s;
                    s = dd[3] * (g[1] * g[20]);
                    s += dd[7] * (g[0] * g[21]);
                    v_iy += (ai2 * g[13] - 2 * g[11]) * s;
                    v_ky += (ak2 * g[17]) * s;
                    v_ly += (al2 * (g[17] - ylyk * g[12])) * s;
                    s = dd[6] * (g[0] * g[20]);
                    v_iy += (ai2 * g[14] - 3 * g[12]) * s;
                    v_ky += (ak2 * g[18]) * s;
                    v_ly += (al2 * (g[18] - ylyk * g[13])) * s;
                    s = dd[0] * (g[3] * g[10]);
                    s += dd[1] * (g[2] * g[11]);
                    s += dd[3] * (g[1] * g[12]);
                    s += dd[6] * (g[0] * g[13]);
                    v_iz += (ai2 * g[21]) * s;
                    v_kz += (ak2 * g[25]) * s;
                    v_lz += (al2 * (g[25] - zlzk * g[20])) * s;
                    s = dd[2] * (g[2] * g[10]);
                    s += dd[4] * (g[1] * g[11]);
                    s += dd[7] * (g[0] * g[12]);
                    v_iz += (ai2 * g[22] - 1 * g[20]) * s;
                    v_kz += (ak2 * g[26]) * s;
                    v_lz += (al2 * (g[26] - zlzk * g[21])) * s;
                    s = dd[5] * (g[1] * g[10]);
                    s += dd[8] * (g[0] * g[11]);
                    v_iz += (ai2 * g[23] - 2 * g[21]) * s;
                    v_kz += (ak2 * g[27]) * s;
                    v_lz += (al2 * (g[27] - zlzk * g[22])) * s;
                    s = dd[9] * (g[0] * g[10]);
                    v_iz += (ai2 * g[24] - 3 * g[22]) * s;
                    v_kz += (ak2 * g[28]) * s;
                    v_lz += (al2 * (g[28] - zlzk * g[23])) * s;
                }
            }
        }
        if (task_id >= ntasks) {
            break;
        }
        int ka = bas[ksh*BAS_SLOTS+ATOM_OF];
        int la = bas[lsh*BAS_SLOTS+ATOM_OF];
        double *ejk = jk.ejk;
        atomicAdd(ejk+ka*3+0, v_kx);
        atomicAdd(ejk+ka*3+1, v_ky);
        atomicAdd(ejk+ka*3+2, v_kz);
        atomicAdd(ejk+la*3+0, v_lx);
        atomicAdd(ejk+la*3+1, v_ly);
        atomicAdd(ejk+la*3+2, v_lz);
        // translational invariance: j's derivative is minus the sum of the other three centers'
        v_jx += v_kx + v_lx;
        v_jy += v_ky + v_ly;
        v_jz += v_kz + v_lz;
    }
    int ia = bas[ish*BAS_SLOTS+ATOM_OF];
    int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
    double *ejk = jk.ejk;
    atomicAdd(ejk+ia*3+0, v_ix);
    atomicAdd(ejk+ia*3+1, v_iy);
    atomicAdd(ejk+ia*3+2, v_iz);
    atomicAdd(ejk+ja*3+0, -(v_ix + v_jx));
    atomicAdd(ejk+ja*3+1, -(v_iy + v_jy));
    atomicAdd(ejk+ja*3+2, -(v_iz + v_jz));
}
